insert into public.cards (id, bron, groep, vraag, antwoord, uitleg, volgorde) values
  ('B001', 'Belfort', 'Kernbegrippen', 'Wat zijn de ''drie tienen'' van Belfort?', 'Zekerheid over het product, over jou en over het bedrijf.', 'De ander moet op alle drie zo dicht mogelijk bij een 10 zitten (op een schaal van 1 tot 10) voordat hij koopt.', 1),
  ('B002', 'Belfort', 'Kernbegrippen', 'Wat is de actiedrempel (action threshold)?', 'De hoeveelheid zekerheid die iemand nodig heeft voordat hij overgaat tot actie.', 'Iedereen heeft een eigen drempel: de een koopt al bij een 7, de ander pas bij een 10.', 2),
  ('B003', 'Belfort', 'Kernbegrippen', 'Hoe verlaag je volgens Belfort iemands actiedrempel?', 'Door het risico weg te nemen, bijvoorbeeld met een garantie, proefperiode of de mogelijkheid om te annuleren.', 'Hoe minder er op het spel lijkt te staan, hoe minder zekerheid iemand nodig heeft om ja te zeggen.', 3),
  ('B004', 'Belfort', 'Kernbegrippen', 'Wat is de pijndrempel (pain threshold)?', 'Het punt waarop de pijn van iemands huidige situatie groot genoeg is om in actie te komen.', 'Pijn is een sterke drijfveer. Door het probleem bespreekbaar en voelbaar te maken, ook naar de toekomst toe, komt iemand eerder in beweging.', 4),
  ('B005', 'Belfort', 'Kernbegrippen', 'Hoe ziet Belfort de meeste bezwaren?', 'Als rookgordijnen: ze verbergen dat de ander nog niet zeker genoeg is.', '''Ik moet erover nadenken'' betekent meestal dat een van de drie tienen nog te laag is. Je werkt dus aan de zekerheid, niet aan het bezwaar zelf.', 5),
  ('B006', 'Belfort', 'Kernbegrippen', 'Wat moet je volgens Belfort in de eerste seconden van een gesprek uitstralen?', 'Dat je scherp bent, enthousiast en een expert in je vakgebied.', 'De ander vormt zich binnen een paar seconden een oordeel; die eerste indruk bepaalt of hij jou serieus neemt.', 6),
  ('B007', 'Belfort', 'Gespreksstructuur', 'Wat beeldt de ''rechte lijn'' uit?', 'De kortste weg van de opening van het gesprek naar de afsluiting, waarbij jij de leiding houdt.', 'Elk verkoopgesprek loopt van open naar close; de verkoper zorgt dat het gesprek die lijn volgt.', 7),
  ('B008', 'Belfort', 'Gespreksstructuur', 'Wat doe je als de ander van de rechte lijn afdwaalt?', 'Je mag even meegaan om rapport op te bouwen, maar binnen de grenzen van de lijn, en dan breng je het gesprek terug.', 'Wie de ander helemaal laat afdwalen, verliest de regie over het gesprek.', 8),
  ('B009', 'Belfort', 'Gespreksstructuur', 'Wat is het doel van de fase ''informatie verzamelen''?', 'Met vragen achterhalen wat de ander nodig heeft, waar zijn pijn zit en of jouw product echt bij hem past.', 'Belfort benadrukt dat je alleen doorgaat met iemand voor wie het product een goede match is.', 9),
  ('B010', 'Belfort', 'Gespreksstructuur', 'Wat volgt in de Straight Line direct na de hoofdpresentatie?', 'De eerste vraag om een besluit (de eerste close).', 'Belfort verwacht dat daar vaak een bezwaar op volgt; dat is het startpunt voor looping.', 10),
  ('B011', 'Belfort', 'Gespreksstructuur', 'Wat is looping?', 'Na een bezwaar terugkeren naar je presentatie om de zekerheid verder te verhogen, en daarna opnieuw om een besluit vragen.', 'Elke loop richt zich op een van de drie tienen of op de actie- of pijndrempel.', 11),
  ('B012', 'Belfort', 'Gespreksstructuur', 'Wat is future pacing in het systeem van Belfort?', 'De ander zich laten voorstellen hoe zijn toekomst eruitziet, met of zonder jouw oplossing.', 'Je kunt er de pijn mee vergroten (zo blijft het als je niets doet) of het positieve beeld versterken.', 12),
  ('B013', 'Belfort', 'Tonaliteit', 'Waarom hecht Belfort zoveel waarde aan tonaliteit en lichaamstaal?', 'Omdat de ander vooral onbewust reageert op hoe je iets zegt, niet alleen op wat je zegt.', 'Woorden spreken het bewuste denken aan; toon en lichaamstaal beïnvloeden het onbewuste oordeel.', 13),
  ('B014', 'Belfort', 'Tonaliteit', 'Welke toon gebruik je om een verzoek redelijk en logisch te laten klinken?', 'De toon van de redelijke man (reasonable man).', 'Licht vragend, zodat het verzoek klinkt als iets waar elk redelijk mens mee instemt.', 14),
  ('B015', 'Belfort', 'Tonaliteit', 'Welke toon laat horen dat iets beperkt beschikbaar is?', 'Schaarste.', 'Vaak met gedempte stem, alsof je iets bijzonders vertelt dat niet iedereen te horen krijgt.', 15),
  ('B016', 'Belfort', 'Tonaliteit', 'Welke toon wekt nieuwsgierigheid op?', 'Mysterie en intrige.', 'Hiermee trek je de aandacht en zorg je dat de ander meer wil horen.', 16),
  ('B017', 'Belfort', 'Tonaliteit', 'Welke toon laat horen dat je volledig achter je woorden staat?', 'Absolute zekerheid.', 'Stellig en vast; je straalt uit dat er geen twijfel over bestaat.', 17),
  ('B018', 'Belfort', 'Tonaliteit', 'Welke toon is kalm, eerlijk en zonder druk?', 'Volledige oprechtheid (utter sincerity).', 'Ingetogen en geloofwaardig; de ander voelt geen verkoopdruk.', 18),
  ('B019', 'Belfort', 'Tonaliteit', 'Welke toon gebruik je als de ander over een probleem vertelt?', 'Ik voel je pijn (I feel your pain).', 'Je laat horen dat je meeleeft met zijn situatie.', 19),
  ('B020', 'Belfort', 'Tonaliteit', 'Welke toon gebruik je tijdens het vragen stellen?', 'Ik wil het echt weten (I care, I really want to know).', 'Oprechte belangstelling, zodat de ander vrijuit vertelt.', 20),
  ('B021', 'Belfort', 'Tonaliteit', 'Welke toon haalt een obstakel zoals geld even weg om een eerlijk antwoord te krijgen?', 'Hypothetisch (geld speelt even geen rol).', 'Door het obstakel tijdelijk weg te denken hoor je wat de ander werkelijk wil.', 21),
  ('B022', 'Belfort', 'Tonaliteit', 'Welke toon laat iets klinken als vanzelfsprekend?', 'Impliciete vanzelfsprekendheid.', 'Je zegt iets alsof het voor de hand ligt, wat het vertrouwen in jouw deskundigheid vergroot.', 22),
  ('B023', 'Belfort', 'Tonaliteit', 'Welke toon gebruik je door een stelling met een stijgende toon te eindigen?', 'Een stelling als vraag uitspreken.', 'De ander knikt onbewust mee; zo verzamel je kleine instemmingen.', 23),
  ('B024', 'Belfort', 'Staat & rapport', 'Hoe bouw je volgens Belfort snel rapport op?', 'Door oprechte zorg te tonen en de ander te spiegelen (matching en mirroring) in toon, tempo en houding.', 'Mensen voelen zich op hun gemak bij iemand die op hen lijkt en om hen geeft.', 24),
  ('B025', 'Belfort', 'Staat & rapport', 'Welke NLP-techniek gebruikt Belfort om zichzelf in een staat van zekerheid te brengen?', 'Ankeren.', 'Hij koppelt een sterke staat van zekerheid aan een vast signaal, zodat hij die staat later kan oproepen.', 25),
  ('B026', 'Belfort', 'Staat & rapport', 'Welk zintuig gebruikt Belfort opvallend voor zijn anker?', 'Geur (een olfactorisch anker).', 'Hij koppelt een specifieke geur aan zijn piekstaat; geur werkt sterk op emotie en geheugen.', 26),
  ('B027', 'Belfort', 'Staat & rapport', 'Wat bedoelt Belfort met ''act as if''?', 'Gedraag je alsof je al de zelfverzekerde, succesvolle persoon bent die je wilt zijn.', 'Door je zo te gedragen, ga je je ook zo voelen en zien anderen je ook zo.', 27),
  ('B028', 'Belfort', 'Achtergrond', 'In welk boek beschrijft Belfort het Straight Line-systeem uitgebreid?', 'Way of the Wolf (2017).', null, 28),
  ('B029', 'Belfort', 'Achtergrond', 'Welke film is gebaseerd op Belforts memoires?', 'The Wolf of Wall Street (2013), geregisseerd door Martin Scorsese.', null, 29),
  ('B030', 'Belfort', 'Achtergrond', 'Welk bedrijf richtte Belfort op?', 'Het effectenbedrijf Stratton Oakmont.', null, 30),
  ('C001', 'Carnegie', 'Basistechnieken', 'Wat doe je volgens Carnegie met kritiek, veroordelen en klagen?', 'Niet doen: bekritiseer, veroordeel en klaag niet.', 'Kritiek maakt mensen defensief; ze gaan zichzelf rechtvaardigen en voelen wrok in plaats van dat ze veranderen.', 31),
  ('C002', 'Carnegie', 'Basistechnieken', 'Welke vorm van waardering raadt Carnegie aan?', 'Eerlijke en oprechte waardering.', 'Carnegie maakt een duidelijk onderscheid tussen oprechte waardering en onoprechte vleierij.', 32),
  ('C003', 'Carnegie', 'Basistechnieken', 'Hoe krijg je volgens Carnegie iemand in beweging?', 'Wek bij de ander een sterk verlangen op.', 'Praat over wat de ander wil en laat zien hoe hij het kan krijgen, niet over wat jij wilt.', 33),
  ('C004', 'Carnegie', 'Aardig gevonden worden', 'Wat is voor Carnegie de basis om aardig gevonden te worden?', 'Toon oprechte belangstelling voor anderen.', 'Je maakt meer vrienden door je voor anderen te interesseren dan door te proberen hen voor jou te interesseren.', 34),
  ('C005', 'Carnegie', 'Aardig gevonden worden', 'Welk eenvoudig, non-verbaal principe noemt Carnegie?', 'Glimlach.', 'Een glimlach zegt zonder woorden dat je de ander graag ziet.', 35),
  ('C006', 'Carnegie', 'Aardig gevonden worden', 'Waarom moet je iemands naam onthouden?', 'Omdat iemands naam voor hem het mooiste en belangrijkste geluid is, in welke taal ook.', 'Een naam onthouden en gebruiken laat zien dat je iemand belangrijk vindt.', 36),
  ('C007', 'Carnegie', 'Aardig gevonden worden', 'Hoe word je volgens Carnegie een goede gesprekspartner?', 'Wees een goede luisteraar en moedig de ander aan over zichzelf te praten.', 'Mensen vinden je een prettige gesprekspartner als jij vooral luistert.', 37),
  ('C008', 'Carnegie', 'Aardig gevonden worden', 'Waarover praat je volgens Carnegie het best?', 'Over de interesses van de ander.', 'Zo raak je wat voor de ander belangrijk is.', 38),
  ('C009', 'Carnegie', 'Aardig gevonden worden', 'Welk diep verlangen spreek je volgens Carnegie aan?', 'Zorg dat de ander zich belangrijk voelt, en doe het oprecht.', 'Het verlangen om belangrijk te zijn is volgens Carnegie een van de sterkste menselijke drijfveren.', 39),
  ('C010', 'Carnegie', 'Overtuigen', 'Hoe win je volgens Carnegie een discussie?', 'Door haar uit de weg te gaan.', 'Ook als je ''wint'', verliest de ander gezichtsverlies en houd je er geen welwillendheid aan over.', 40),
  ('C011', 'Carnegie', 'Overtuigen', 'Hoe ga je om met de mening van een ander?', 'Toon respect voor zijn mening en zeg nooit dat hij ongelijk heeft.', 'Iemand rechtstreeks tegenspreken maakt hem alleen vastberadener in zijn standpunt.', 41),
  ('C012', 'Carnegie', 'Overtuigen', 'Wat doe je als je zelf ongelijk hebt?', 'Geef het snel en ronduit toe.', 'Wie zijn fout zelf erkent, neemt de ander de wind uit de zeilen en wint respect.', 42),
  ('C013', 'Carnegie', 'Overtuigen', 'Hoe begin je een gesprek waarin je iemand wilt overtuigen?', 'Op een vriendelijke manier.', 'Vriendelijkheid opent deuren die je met druk dichtduwt.', 43),
  ('C014', 'Carnegie', 'Overtuigen', 'Welk soort antwoorden wil je vroeg in het gesprek krijgen?', 'Zorg dat de ander meteen ''ja, ja'' zegt.', 'Begin met punten waarover je het eens bent; een vroeg ''nee'' is moeilijk terug te draaien.', 44),
  ('C015', 'Carnegie', 'Overtuigen', 'Wie moet volgens Carnegie het meest aan het woord zijn?', 'De ander: laat hem het grootste deel van het gesprek voeren.', 'Wie veel praat, voelt zich gehoord en staat meer open voor jouw punt.', 45),
  ('C016', 'Carnegie', 'Overtuigen', 'Van wie moet het idee lijken te komen?', 'Van de ander: laat hem voelen dat het zijn idee is.', 'Mensen hechten meer aan ideeën die ze zelf hebben bedacht.', 46),
  ('C017', 'Carnegie', 'Overtuigen', 'Vanuit wiens standpunt probeer je de zaak te zien?', 'Vanuit dat van de ander, en dan eerlijk.', 'Begrijp eerst waarom de ander denkt wat hij denkt.', 47),
  ('C018', 'Carnegie', 'Overtuigen', 'Hoe reageer je op de ideeën en wensen van de ander?', 'Met begrip en sympathie.', 'Begrip voor iemands gevoelens neemt weerstand weg.', 48),
  ('C019', 'Carnegie', 'Overtuigen', 'Op welke motieven doe je een beroep?', 'Op de edelere motieven.', 'Mensen willen zichzelf graag zien als eerlijk en fatsoenlijk; spreek dat aan.', 49),
  ('C020', 'Carnegie', 'Overtuigen', 'Hoe breng je je ideeën over zodat ze blijven hangen?', 'Dramatiseer ze: maak ze levendig en aanschouwelijk.', 'Alleen de waarheid vertellen is niet genoeg; je moet haar ook levendig maken.', 50),
  ('C021', 'Carnegie', 'Overtuigen', 'Welk principe speelt in op de competitiedrang van mensen?', 'Daag de ander uit.', 'De wens om te excelleren en zichzelf te bewijzen is een sterke motivatie.', 51),
  ('C022', 'Carnegie', 'Leiderschap', 'Waarmee begin je als je iemand wilt corrigeren?', 'Met lof en oprechte waardering.', 'Na waardering is kritiek makkelijker te horen.', 52),
  ('C023', 'Carnegie', 'Leiderschap', 'Hoe wijs je iemand op zijn fouten?', 'Indirect.', 'Een directe aanval roept verzet op; een indirecte aanwijzing laat ruimte.', 53),
  ('C024', 'Carnegie', 'Leiderschap', 'Waarover praat je voordat je iemand bekritiseert?', 'Over je eigen fouten.', 'Als jij eerst toegeeft dat je zelf ook fouten maakt, voelt de kritiek minder als een aanval.', 54),
  ('C025', 'Carnegie', 'Leiderschap', 'Wat doe je in plaats van directe opdrachten geven?', 'Stel vragen.', 'Vragen laten de ander meedenken en geven hem een gevoel van eigenaarschap.', 55),
  ('C026', 'Carnegie', 'Leiderschap', 'Wat gun je de ander altijd, ook als hij fout zit?', 'Dat hij zijn gezicht kan redden.', 'Iemand vernederen kost je zijn medewerking.', 56),
  ('C027', 'Carnegie', 'Leiderschap', 'Welke verbeteringen prijs je?', 'Elke verbetering, ook de kleinste, en dan hartelijk en royaal.', 'Lof voor kleine stappen stimuleert de volgende stap.', 57),
  ('C028', 'Carnegie', 'Leiderschap', 'Wat geef je iemand om waar te maken?', 'Een goede reputatie.', 'Mensen doen hun best om te leven naar het beeld dat jij van hen schetst.', 58),
  ('C029', 'Carnegie', 'Leiderschap', 'Hoe laat je een fout klein lijken?', 'Moedig aan en laat de fout makkelijk te herstellen lijken.', 'Als iets haalbaar voelt, gaat iemand ermee aan de slag.', 59),
  ('C030', 'Carnegie', 'Leiderschap', 'Hoe zorg je dat iemand graag doet wat je voorstelt?', 'Zorg dat de ander blij is met wat jij voorstelt.', 'Laat zien wat het voor hem oplevert.', 60),
  ('C031', 'Carnegie', 'Zorgen overwinnen', 'Hoe ga je volgens Carnegie met tijd om als je piekert?', 'Leef in dagcompartimenten: richt je op vandaag.', 'Laat het verleden en de toekomst los en doe wat vandaag gedaan moet worden.', 61),
  ('C032', 'Carnegie', 'Zorgen overwinnen', 'Wat is de ''magische formule'' van Willis Carrier?', 'Vraag je af wat het ergste is dat kan gebeuren, aanvaard dat, en werk er dan aan om het ergste te verbeteren.', 'Door het ergste te aanvaarden komt je energie vrij om aan een oplossing te werken.', 62),
  ('C033', 'Carnegie', 'Zorgen overwinnen', 'Hoe relativeer je een zorg met kansberekening?', 'Gebruik de wet van de gemiddelden: hoe groot is de kans echt?', 'De meeste dingen waarover we piekeren, gebeuren nooit.', 63),
  ('C034', 'Carnegie', 'Zorgen overwinnen', 'Wat doe je met wat je niet kunt veranderen?', 'Werk mee met het onvermijdelijke.', 'Wat niet te veranderen is, kun je beter aanvaarden dan bevechten.', 64),
  ('C035', 'Carnegie', 'Zorgen overwinnen', 'Hoe begrens je hoeveel zorg je ergens aan besteedt?', 'Zet een stop-loss-order op je zorgen.', 'Bepaal hoeveel aandacht iets waard is, en geef het niet meer dan dat.', 65),
  ('C036', 'Carnegie', 'Zorgen overwinnen', 'Hoe kijk je naar onterechte kritiek?', 'Als een verkapt compliment.', 'Niemand schopt tegen een dode hond: kritiek betekent vaak dat je iets voorstelt.', 66),
  ('C037', 'Carnegie', 'Zorgen overwinnen', 'Waar richt je je aandacht op om zorgen te verminderen?', 'Tel je zegeningen, niet je problemen.', 'Aandacht voor wat goed gaat, verandert hoe je je voelt.', 67),
  ('C038', 'Carnegie', 'Zorgen overwinnen', 'Wat is een eenvoudige remedie tegen piekeren?', 'Blijf bezig.', 'Een druk hoofd heeft weinig ruimte om te piekeren.', 68),
  ('C039', 'Carnegie', 'Zorgen overwinnen', 'Wat bedoelt Carnegie met ''geen zaagsel zagen''?', 'Pieker niet over het verleden: wat voorbij is, kun je niet meer veranderen.', 'Zaagsel is al gezaagd; opnieuw zagen levert niets op.', 69),
  ('C040', 'Carnegie', 'Zorgen overwinnen', 'Wat doe je volgens Carnegie met de neiging om wraak te nemen?', 'Niet doen: probeer niet met je vijanden af te rekenen.', 'Wraak kost jou meer dan de ander; het vreet aan je eigen rust.', 70),
  ('C041', 'Carnegie', 'Zorgen overwinnen', 'Wat verwacht je volgens Carnegie van anderen als het om dankbaarheid gaat?', 'Verwacht geen dankbaarheid.', 'Geef om het geven; dan word je niet teleurgesteld en is elke dankbetuiging een cadeau.', 71),
  ('C042', 'Carnegie', 'Zorgen overwinnen', 'Wat doe je volgens Carnegie als je een citroen krijgt?', 'Maak er limonade van.', 'Probeer van een tegenslag iets waardevols te maken.', 72),
  ('C043', 'Carnegie', 'Zorgen overwinnen', 'Hoe vergeet je je eigen zorgen volgens Carnegie?', 'Door je te interesseren voor anderen en iets voor hen te doen.', 'Aandacht voor anderen haalt je uit je eigen gepieker.', 73),
  ('C044', 'Carnegie', 'Zorgen overwinnen', 'Wat is Carnegies advies over jezelf zijn?', 'Ontdek wie je bent en wees jezelf; doe anderen niet na.', 'Je bent uniek; imitatie levert nooit je beste werk op.', 74),
  ('C045', 'Carnegie', 'Zorgen overwinnen', 'Hoe ga je om met kritiek als je je best hebt gedaan?', 'Doe je uiterste best en laat de kritiek daarna los.', 'Je kunt niet voorkomen dat er kritiek komt, wel hoeveel je ermee doet.', 75),
  ('C046', 'Carnegie', 'Achtergrond', 'In welk jaar verscheen How to Win Friends and Influence People?', '1936.', null, 76),
  ('C047', 'Carnegie', 'Achtergrond', 'Welk boek van Carnegie gaat over het overwinnen van zorgen?', 'How to Stop Worrying and Start Living (1948).', null, 77)
